package com.supportsphere.service; import com.supportsphere.dao.*; import com.supportsphere.exception.*; import com.supportsphere.model.*; import java.sql.*; import java.util.*; public class AuthService {private final UserDAO dao=new UserDAO(); public User login(String e,String p)throws Exception{Optional<User>u=dao.authenticate(e.trim(),p);if(u.isEmpty())throw new AuthenticationException("Invalid email or password, or your account is blocked.");return u.get();} public int register(String n,String e,String p,String ph,Role r,String a,String c,String l,String notes,int exp,Time s,Time end,List<String> skills)throws Exception{if(n.isBlank()||e.isBlank()||p.length()<6||ph.isBlank())throw new ValidationException("Please provide valid name, email, password (6+ characters) and phone.");if(r==Role.VOLUNTEER&&(skills==null||skills.isEmpty()))throw new ValidationException("Select at least one volunteer skill.");return dao.register(n,e,p,ph,r,a,c,l,notes,exp,s,end,skills);} }
